={{ 
  (() => {
    try {
      // 1. Capturar el texto crudo proveniente del nodo chain de manera segura
      let rawText = "";
      if ($json.text) {
        rawText = $json.text;
      } else if ($json.resultado && typeof $json.resultado === 'string') {
        rawText = $json.resultado;
      } else if (typeof $json === 'string') {
        rawText = $json;
      } else {
        rawText = JSON.stringify($json);
      }

      // 2. Limpiar posibles saltos de línea e intentar capturar la estructura del objeto JSON
      rawText = rawText.replace(/\\n/g, "\n");
      const jsonMatch = rawText.match(/\{[\s\S]*\}/);

      if (!jsonMatch) throw new Error("Estructura JSON no encontrada");

      // 3. Remover bloques de formato markdown si el modelo los incluyó
      const cleanText = jsonMatch[0].replace(/```json|```/g, "").trim();
      const parsed = JSON.parse(cleanText);

      // 4. Asegurar que la puntuación se guarde como un valor numérico limpio para el nodo Sort
      let score = 0;
      if (parsed.puntuacion !== undefined) {
        score = parseInt(parsed.puntuacion, 10) || 0;
      }

      // 5. Devolver las propiedades normalizadas en la raíz del objeto
      return {
        analisis: parsed.analisis || "Sin análisis disponible.",
        puntuacion: score,
        sugerencia: parsed.sugerencia || "Sin sugerencia disponible."
      };

    } catch (e) {
      // Fallback de contingencia en caso de error de parseo
      return { 
        analisis: "Error al procesar el formato de la IA.",
        puntuacion: 0,
        sugerencia: "Por favor, verificar la salida cruda devuelta por OpenRouter."
      };
    }
  })()
}}

