// 1. Obtenemos los datos del elemento actual de forma directa
const item = $json;

// 2. Copiamos el objeto original para no perder ninguna propiedad
let cleanJson = { ...item };

// 3. Estandarización de Títulos (Title Case básico y limpieza de espacios)
if (cleanJson.title) {
  cleanJson.title = cleanJson.title
    .trim() // Elimina espacios al inicio y al final
    .replace(/\s+/g, ' ') // Reemplaza múltiples espacios por uno solo
    .toLowerCase()
    .replace(/\b\w/g, c => c.toUpperCase()); // Convierte a Title Case
}

// 4. Limpieza del contenido/resumen (Remover etiquetas HTML si las hay)
if (cleanJson.summary) {
  cleanJson.summary = cleanJson.summary
    .replace(/<\/?[^>]+(>|$)/g, "") // Elimina cualquier etiqueta HTML oculta
    .trim()
    .replace(/\s+/g, ' ');
}

if (cleanJson.content) {
  cleanJson.content = cleanJson.content
    .replace(/<\/?[^>]+(>|$)/g, "")
    .trim()
    .replace(/\s+/g, ' ');
}

// 5. Devolvemos el JSON limpio listo para el siguiente nodo
return { json: cleanJson };
